\begin{align*}
&\sigma(y_t) - \sigma(y_v) \\
&=
\frac{\frac{1}{s} \sum_{i \le s} p_{(i)}(y_t)}
     {\frac{1}{n} \sum_{i=1}^{n} p_i(y_t)}
-
\frac{\frac{1}{s} \sum_{i \le s} p_{(i)}(y_v)}
     {\frac{1}{n} \sum_{i=1}^{n} p_i(y_v)}
\\[2mm]
&=
\frac{
\left( \frac{1}{s} \sum_{i \le s} p_{(i)}(y_t) \right)
\left( \frac{1}{n} \sum_{i=1}^{n} p_i(y_v) \right)
-
\left( \frac{1}{s} \sum_{i \le s} p_{(i)}(y_v) \right)
\left( \frac{1}{n} \sum_{i=1}^{n} p_i(y_t) \right)
}{
\left( \frac{1}{n} \sum_{i=1}^{n} p_i(y_t) \right)
\left( \frac{1}{n} \sum_{i=1}^{n} p_i(y_v) \right)
}
\\[2mm]
&=
\frac{n}{s} \cdot
\frac{
\left( \sum_{i \le s} p_{(i)}(y_t) \right)
\left( \sum_{i=1}^{n} p_i(y_v) \right)
-
\left( \sum_{i \le s} p_{(i)}(y_v) \right)
\left( \sum_{i=1}^{n} p_i(y_t) \right)
}{
\left( \sum_{i=1}^{n} p_i(y_t) \right)
\left( \sum_{i=1}^{n} p_i(y_v) \right)
}
\\[2mm]





















&=
\frac{n}{s} \cdot
\frac{
\left( \sum_{i \le s} p_{(i)}(y_t) \right)
\left( \sum_{i > s} p_{(i)}(y_v) \right)
-
\left( \sum_{i \le s} p_{(i)}(y_v) \right)
\left( \sum_{i > s} p_{(i)}(y_t) \right)
}{
\left( \sum_{i=1}^{n} p_i(y_t) \right)
\left( \sum_{i=1}^{n} p_i(y_v) \right)
}
\end{align*}

